package com.onlinelibrary.controller;
import com.onlinelibrary.dao.impl.NotificationDAOImpl; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/member/notifications") public class NotificationServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{var d=new NotificationDAOImpl();r.setAttribute("notifications",d.findForMember(WebSupport.uid(r)));r.setAttribute("unread",d.unreadCount(WebSupport.uid(r)));WebSupport.view(r,s,"notifications.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{new NotificationDAOImpl().markRead(WebSupport.uid(r),Long.parseLong(r.getParameter("notificationId")));s.sendRedirect(r.getContextPath()+"/member/notifications");}catch(Exception e){WebSupport.fail(r,s,e);}}}
